SELECT DISTINCT ?value WHERE {
                            ?value a <{class_uri}> .
                            }

example_usage:
SELECT DISTINCT ?value WHERE {
                            ?value a <http://purl.dataone.org/provone/2015/01/15/ontology#Execution> .
